return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-09-08T20:38:11+00:00','po-revision-date'=>'2026-09-08T20:38:11+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'Objavljuje ovaj sajt na svakom jeziku koji izaberete, na sopstvenim veb-adresama, sa prevedenim slug-ovima, metapodacima, menijima, WooCommerce proizvodima, hreflang oznakama, mapama sajta za svaki jezik i llms.txt datotekom. Prevodite uz svoj Zinn Digital® paket ili pomoću sopstvenog ključa provajdera.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Sačuvano. Unesite novu vrednost da biste je zamenili.','Filter this list…'=>'Filtriraj ovu listu…','Filter this list'=>'Filtriraj ovu listu','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj red','Remove this row'=>'Ukloni ovaj red','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® dodatak na ovom sajtu, kao i da li radi.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna veza.','Open settings'=>'Otvorite podešavanja','You do not have permission to change these settings.'=>'Nemate dozvolu da menjate ova podešavanja.','Settings sections'=>'Sekcije podešavanja','Support'=>'Podrška','Save changes'=>'Sačuvaj izmene','Tools'=>'Alatke','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na podrazumevane vrednosti','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svako podešavanje ovog dodatka na podrazumevane vrednosti. Želite li da nastavite?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezi datoteku podešavanja','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, token-ključeve niti API ključeve — moraćete ponovo da ih unesete na novom sajtu.','Settings saved.'=>'Podešavanja su sačuvana.','Every setting on this plugin is back to its default.'=>'Svako podešavanje na ovom dodacima je vraćeno na podrazumevane vrednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Ta datoteka se nije mogla pročitati. Izaberite datoteku sa podešavanjima izvezenu iz Zinn® dodatka.','That file is too large to be a settings export.'=>'Ta datoteka je prevelika da bi bila izvoz podešavanja.','That file is not a Zinn® settings export.'=>'Taj fajl nije izvoz podešavanja za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Taj fajl je uvezen iz drugog dodatka (%s), tako da bi njegovo uvoz ovde sačuvalo podešavanja koja ovaj dodatak ne prepoznaje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d podešavanje uvezeno. Lozinke i API ključevi se nikada ne nalaze u izvozu, pa ih unesite ponovo.' . "\0" . '%d podešavanja su uvežena. Lozinke i API ključevi se nikada ne izvoze, pa ih unesite ponovo.' . "\0" . '%d podešavanja su uvežena. Lozinke i API ključevi se nikada ne izvoze, pa ih unesite ponovo.','Translate'=>'Prevedi','Manual overrides'=>'Ručne izmene','Sitemaps and URLs'=>'Sitemapi i URL-ovi','General'=>'Opšte','Who pays for the translation'=>'Ko plaća prevod','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'Bilo Vaš Zinn Digital® paket, bilo Vaš sopstveni API ključ. Ne postoji besplatni paket — neko plaća provajderu za svaku reč.','My Zinn Digital® plan'=>'Moj Zinn Digital® paket','My own provider key'=>'Moj sopstveni ključ provajdera','Site ID'=>'ID sajta','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'Sa vaše Zinn Digital® komandne table, na kartici Prevod za ovaj sajt.','Site token'=>'Token sajta','Provider'=>'Provajder','API key'=>'API ključ','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'Vaš ključ, koji vam naplaćuje provajder. On se čuva na ovom sajtu i šalje se samo njima.','Model'=>'Model','Leave empty for the cheapest model that does the job well.'=>'Ostavite prazno za najjeftiniji model koji dobro obavlja posao.','This site is written in'=>'Ovaj sajt je napisan na','Leave empty to use the site language from WordPress settings.'=>'Ostavite prazno da biste koristili jezik sajta iz WordPress podešavanja.','Languages to publish'=>'Jezici za objavljivanje','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'Svaka dobija sopstvene veb adrese i sopstvenu mapu sajta. Objavite samo one jezike koje želite da budu indeksirani.','Translate automatically when I publish or update'=>'Prevedi automatski kada objavim ili ažuriram','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'Izmena stranice označava njene prevode zastarelim i oni se ponovo prave u pozadini. Izmena bez menjanja reči ništa ne košta.','What gets translated'=>'Šta se prevodi','Post types'=>'Tipovi objava','Translate the web addresses too'=>'Prevedite i veb adrese','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'Francuski posetioci dobijaju /fr/a-propos/ umesto /fr/about/. Netranslatirana adresa nastavlja da radi i preusmerava, tako da se ništa što je indeksirano ne kvari.','Translate SEO titles, descriptions and image alt text'=>'Prevedite SEO naslove, opise i alt tekst slika','Translate categories and tags'=>'Prevedi kategorije i oznake','Translate navigation menus'=>'Prevedi navigacione menije','Translate WooCommerce products and attributes'=>'Prevedite WooCommerce proizvode i atribute','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'Kratki opisi, beleške o kupovini, oznake atributa i opisi varijacija. Cene, SKU-ovi i sačuvane vrednosti opcija se nikada ne diraju.','SEO'=>'SEO','Add hreflang tags'=>'Dodajte hreflang oznake','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'Govori pretraživačima da su ove stranice ista stranica na različitim jezicima. Ostavite ovo uključeno osim ako drugi dodatak to već ne radi.','Publish a sitemap for each language'=>'Objavite mapu sajta za svaki jezik','Publish llms.txt for each language'=>'Objavi llms.txt za svaki jezik','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'Mapa sajta u čistom tekstu koju čitaju AI mašine za odgovore. One često ne mogu da pokreću JavaScript i možda nikada neće preuzeti mapu sajta.','Language switcher'=>'Jezik prekidač','Style'=>'Stil','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'Boje, razmaci i uglovi nalaze se na kartici Stil. Postavite ga sa blokom, kratkim kodom [zinn_language_switcher] ili menijem.','Show only these languages'=>'Prikaži samo ove jezike','Leave empty to show every language you publish.'=>'Оставите празно да се прикажу сви језици које објављујете.','Name each language in its own language'=>'Imenujte svaki jezik na njegovom sopstvenom jeziku','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'Deutsch umesto German. Neko ko ne može da čita trenutnu stranicu ne može da čita ni „German“.','Show flags'=>'Prikaži zastavice','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'Isključeno po podrazumevanoj vrednosti: jezik nije država, a arapski i španski nemaju jednu jedinu zastavu koja ne isključuje većinu njihovih govornika.','Include the language being read'=>'Uključi jezik koji se čita','Include the original language'=>'Uključi originalni jezik','Add it to this menu'=>'Dodajte ga u ovaj meni','Only the menu you name here. Nothing is added to any other menu on the site.'=>'Samo meni koji ovde navedete. Ništa se ne dodaje nijednom drugom meniju na sajtu.','Accent'=>'Акцент','Background'=>'Pozadina','Text'=>'Tekst','Corner radius'=>'Radijus ugla','Spacing'=>'Razmak','Text size'=>'Veličina teksta','Do not add it to a menu'=>'Nemojte ga dodavati u meni','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'Ovde možete urediti bilo koji prevod. Uređeni prevod se čuva tačno onako kako ste ga napisali i nikada se ne prepisuje kada se stranica ponovo prevodi.','Every language'=>'Svaki jezik','Search translations'=>'Pretraži prevode','Filter'=>'Филтер','Content'=>'Sadržaj','Language'=>'Jezik','Translation'=>'Prevod','Status'=>'Status','Save'=>'Сачувај','Nothing translated yet. Publish a language and translation starts in the background.'=>'Ništa još nije prevedeno. Objavite jezik i prevod počinje u pozadini.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'Ove adrese su aktivne. Otvorite bilo koju od njih da biste je proverili i pošaljite indeks sitemapa na Google Search Console.','You are not allowed to edit translations on this site.'=>'Nije vam dozvoljeno da uređujete prevode na ovoj veb-lokaciji.','Edited by you — kept'=>'Uredili ste Vi — sačuvano','Source changed — will be redone'=>'Izvor je promenjen — biće ponovljeno','Up to date'=>'Ažurno','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahteva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Pokretanje sa vašeg sopstvenog naloga','We could not check this'=>'Nismo mogli da proverimo ovo','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostički izveštaj i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Poslednji put provereno pre %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Ovo je tačno ono što će biti poslato — ništa drugo, i ništa sakriveno. Vaše lozinke, tokeni i API ključevi nisu u tome.','The diagnostics report that will be sent'=>'Dijagnostički izveštaj koji će biti poslat','Copy to clipboard'=>'Kopiraj u ostavu','Send this report to Zinn® support'=>'Pošaljite ovaj izveštaj Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Mi otvaramo tiket za podršku za vas i odgovaramo putem e-pošte. Ako više volite da ga ne šaljete, kopirajte ga iznad i sami ga nalepite u tiket.','Copied'=>'Kopirano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli da uspostavimo vezu sa Zinn Digital® sa ovog servera (%s). Umesto toga kopirajte izveštaj iznad i otvorite tiket — sa vašim podešavanjima je sve u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Poslato. Zinn® podrška je primila vaš izveštaj i odgovoriće vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Poslato. Zinn® podrška je primila vaš izveštaj — referenca %s — i odgovoriće vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izveštaja u kratkom vremenskom roku. Sačekajte nekoliko minuta i pokušajte ponovo — prethodni su stigli.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao da prihvati izveštaj — to je problem sa naše strane, a ne vaše. Pokušajte ponovo uskoro ili kopirajte izveštaj iznad u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izveštaj je odbijen (HTTP %d). Kopirajte ga iznad i otvorite tiket, navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnička uputstva','Read the %s user guide'=>'Pročitajte %s korisničko uputstvo','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne rezervne kopije, besplatna migracija i kontrolna tabla napravljena za ljude koji vode više od jednog sajta.','The Zinn® marketplace'=>'Zinn® pijaca','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite već uspostavljene sajtove, domene i postavljanja linkova, pri čemu se novac drži na sigurnom dok obe strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažujte ljude koji se time bave profesionalno','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište honorarnih poslova: pregledajte preko 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka, ili objavite projekat i dozvolite im da licitiraju.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'API ključ je odbijen. Proverite da li je i dalje važeći i da li ima pristup prevodu, a zatim ga ponovo sačuvajte.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'Dobavljač je odbio zbog naplate ili kvote. Ništa nije prevedeno. Proverite stanje i limite na svom računu kod njih.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'Ponuđač usluge prevođenja ima problem na svojoj strani. Ništa nije prevedeno niti naplaćeno, i biće pokušano ponovo u sledećem ciklusu.','The translation request failed and we could not tell why. Nothing was saved.'=>'Zahtev za prevod nije uspeo i nismo mogli da utvrdimo zašto. Ništa nije sačuvano.','Sitemap index'=>'Indeks sitemapa','%s sitemap'=>'%s sitemap','LLM content map'=>'Мапа садржаја за LLM','%s LLM content map'=>'%s LLM mapa sadržaja','Languages published'=>'Objavljeni jezici','Site language'=>'Jezik sajta','SEO plugin'=>'SEO dodatak','No translation provider is set up yet.'=>'Ниједан провајдер за превод још увек није подешен.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'Nalepite API ključ od izabranog provajdera ili povežite sajt sa Zinn Digital® nalogom, i prevođenje počinje u sledećem prolazu.','Translating with your own %s key.'=>'Prevođenje pomoću sopstvenog %s ključa.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'Ovaj sajt nije povezan sa nalogom na Zinn Digital®-u, što je u redu — vaš provajder vam fakturiše direktno.','Not connected to Zinn Digital® yet.'=>'Još uvek niste povezani sa Zinn Digital®.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'Dodajte ID i token ovog sajta sa svoje Zinn Digital® kontrolne table ili pređite na sopstveni ključ provajdera da biste radili bez naloga.','Connected to Zinn Digital®.'=>'Povezano sa Zinn Digital®.','The translation provider is having a problem.'=>'Dobavljač za prevod ima problem.','Translation is paused — your provider needs attention.'=>'Prevođenje je pauzirano — vaš provajder zahteva pažnju.','Translation has not been set up yet.'=>'Prevod još uvek nije podešen.','Something went wrong at our end.'=>'Došlo je do greške sa naše strane.','Check their status page'=>'Proverite njihovu stranicu sa statusom','Fix this on your account'=>'Popravite ovo na svom nalogu','Style preset'=>'Stilski predefinisani set','A starting point. Anything below overrides it.'=>'Polazna tačka. Sve ispod ovoga ima prednost.','Use my own colours and sizes'=>'Koristi sopstvene boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Isključite ovo i unapred podešena vrednost se koristi tačno takva kakva jeste.','Zinn® language switcher'=>'Zinn® jezički prekidač','Let visitors read this page in another language.'=>'Omogućite posetiocima da čitaju ovu stranicu na drugom jeziku.','Title'=>'Naslov','Use the plugin setting'=>'Koristi postavku dodatka','Dropdown'=>'Padajući meni','Inline list'=>'Ugrađena lista','Pills'=>'Kartice','Minimal text'=>'Minimalni tekst','Flags and names'=>'Заставе и имена','Stacked list'=>'Stepenasta lista','Choose a language'=>'Izaberite jezik','See the Zinn Digital® release notes.'=>'Pogledajte napomene o izdanju za Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo proveru integriteta i nije instalirano.','No DeepL API key is saved, so there is nothing to translate with.'=>'Nijedan DeepL API ključ nije sačuvan, tako da nema ničega sa čime bi se moglo prevoditi.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL ne prevodi na %s. Izaberite Google Gemini ili OpenAI za ovaj jezik ili povežite sajt sa Zinn Digital®.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije moguće uspostaviti vezu sa uslugom DeepL. Ništa nije prevedeno niti naplaćeno; usluga će pokušati ponovo u sledećem prolazu.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'Vaša kvota karaktera za DeepL je iskorišćena za ovaj period. Prevođenje se nastavlja kada se ona resetuje ili kada povećate limit na svom DeepL nalogu.','DeepL answered with something we could not read. Nothing was saved.'=>'DeepL je odgovorio sa nečim što nismo mogli da pročitamo. Ništa nije sačuvano.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Nijedan Google Gemini API ključ nije sačuvan, tako da nema ničega sa čime bi se prevodilo.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Google Gemini se nije mogao kontaktirati. Ništa nije prevedeno i ništa nije naplaćeno; pokušaće ponovo u sledećem prolazu.','No OpenAI API key is saved, so there is nothing to translate with.'=>'Nije sačuvan nijedan OpenAI API ključ, tako da nema ničega sa čim bi se prevodilo.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'OpenAI se nije mogao dobiti. Ništa nije prevedeno i ništa nije naplaćeno; pokušaće ponovo u sledećem prolazu.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'Ovaj sajt nije povezan sa Zinn Digital®, tako da nema ničega za prikupljanje. Dodajte ID sajta i token ili pređite na sopstveni ključ provajdera.','This site is not connected to Zinn Digital®.'=>'Ovaj sajt nije povezan sa kompanijom Zinn Digital®.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'Zinn Digital® se nije mogao kontaktirati. Ništa nije poslano; pokušaće ponovo u sledećem ciklusu.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'Prevod je pauziran na ovom sajtu. Proverite da li je nalog ažuran na vašoj Zinn Digital® kontrolnoj tabli.','Zinn Digital® rejected this site\'s token. Copy it again from the site\'s Translation tab on your dashboard.'=>'Zinn Digital® je odbio token ove lokacije. Ponovo ga kopirajte sa kartice za prevod na kontrolnoj tabli lokacije.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'Zinn Digital® nije mogao biti dostupan. Vaš sajt nastavlja da isporučuje prevode koje već ima.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Zinn Digital® je odgovorio sa nečim što nismo mogli da pročitamo. Vaš sajt nastavlja da isporučuje prevode koje već ima.']];